import{z as i,x as p,o as t,c as A,q as s,j as n,D as r,d as o,s as l,S as B,b as e}from"./chunks/framework.C8m1ZpeB.js";const m=JSON.parse('{"title":"Zab 与 ZooKeeper","description":"","frontmatter":{"title":"Zab 与 ZooKeeper","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/zab-zookeeper.md","filePath":"cs/zab-zookeeper.md","lastUpdated":1791063341000}'),d={name:"cs/zab-zookeeper.md"};function D(b,a,u,Z,c,f){const E=p("Mermaid");return t(),A("div",null,[a[2]||(a[2]=s('<h1 id="zab-与-zookeeper" tabindex="-1">Zab 与 ZooKeeper <a class="header-anchor" href="#zab-与-zookeeper" aria-label="Permalink to &quot;Zab 与 ZooKeeper&quot;">​</a></h1><div class="epigraph"><p>Zab 给前缀一致的广播：同一纪元里领导者的事务全序，切换纪元时新主对齐已提交前缀。ZooKeeper 用它实现文件系统 API 的线性一致元数据。</p><footer>—— 据 Hunt, Konar, Junqueira and Reed, ZooKeeper, USENIX ATC 2010；Junqueira, Reed and Serafini, Zab, DSN 2011 整理</footer></div><p>上一课<a href="/cs/raft-membership-snapshot">Raft 成员与快照</a>讲了日志上的配置。缺口是<strong>另一条被广泛跑的日志协议</strong>：ZooKeeper 不是 Raft 实现，它用 Zab。本课对照 RSM 形状，不重写 Raft 投票。后课 VR 更早，是第三条亲戚。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Zab 保证：已交付的事务形成全序；新领导者恢复时，已提交前缀不丢、未达多数派的尾可丢。纪元（epoch）类似 term。发现与同步阶段选出领导者并补齐跟随者，广播阶段流水线事务。ZXID 高位纪元、低位计数，比较规则钉「更新的日志」。</p><p>ZooKeeper API：znode、watch、顺序节点。客户端会话带<a href="/cs/leases">租约</a>式超时。写走领导者，读可走跟随者——默认读不是线性一致，<code>sync</code> 后读才追上。这是<a href="/cs/session-guarantees">会话</a>与 RSM 的交界：产品把弱读当默认。</p><p><span class="marginnote">数字实例：ZXID 是 64 位整数，高 32 位是纪元、低 32 位是计数——纪元 3、计数 17 就拼成 0x0000000300000011。比较先比纪元再比计数，「哪份日志更新」的定义就钉在这条比较规则上，选举时凭它裁定胜负。</span></p><p><span class="marginnote">ATC 2010 讲服务；DSN 2011 讲 Zab。Chubby 用 Paxos，下一课再钉锁服务对照。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>写：领导者赋 ZXID，多数派持久后交付状态机。watch：对 znode 的一次性回调，不是总线级可靠订阅——丢失要靠版本再读。成员：集成在 ZooKeeper 自身，配置也是 znode 树的一部分加法定人数。</p><p><span class="marginnote">术语翻译：watch 是&quot;一次性门铃&quot;——在某个 znode 上挂铃，数据变一次铃响一次，然后铃自动拆除；想持续监听就得响一次再挂一次，两次之间的变化要靠读回的版本号补齐。</span></p>',11)),(t(),n(B,null,{default:r(()=>[l(E,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20LD%5B%22%E9%A2%86%E5%AF%BC%E8%80%85%E5%B9%BF%E6%92%AD%22%5D%20--%3E%20ZX%5B%22ZXID%20%E5%85%A8%E5%BA%8F%22%5D%0A%20%20ZX%20--%3E%20MAJ%5B%22%E5%A4%9A%E6%95%B0%E6%B4%BE%E6%8C%81%E4%B9%85%22%5D%0A%20%20MAJ%20--%3E%20DELIV%5B%22%E4%BA%A4%E4%BB%98%22%5D%0A%20%20EP%5B%22%E6%96%B0%E7%BA%AA%E5%85%83%E5%90%8C%E6%AD%A5%22%5D%20--%3E%20PREF%5B%22%E5%AF%B9%E9%BD%90%E5%B7%B2%E6%8F%90%E4%BA%A4%E5%89%8D%E7%BC%80%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"与 Raft：都是稳定主日志。Zab 强调广播原语的前缀性质；Raft 强调可理解的状态机与日志匹配。不要把二者当互为形式化翻译而不看提交规则差异。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[o("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"线性一致写：多数派 ack。线性一致读：读领导者或 sync。Chubby 风格的锁在 ZK 上用临时顺序节点实现——那是后课锁与 fencing 的例子，本课只指出 API 能做。脑裂：旧领导者纪元落后，写被拒。",-1)),a[6]||(a[6]=e("p",null,[e("span",{class:"marginnote"},[o('常见误区：初学者容易把 ZooKeeper 当强一致读缓存用。实际默认跟随者读只保证会话内单调、跨会话可旧——做选主、注册元数据这类依赖"读到的一定是最新"的操作时，必须显式 '),e("code",null,"sync"),o(" 或读领导者，否则可能拿到旧主纪元的残留值。")])],-1)),(t(),n(B,null,{default:r(()=>[l(E,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20C%5B%22%E5%AE%A2%E6%88%B7%E7%AB%AF%E5%8F%91%E8%B5%B7%E8%AF%BB%22%5D%20--%3E%20W%7B%22%E9%80%89%E5%93%AA%E6%9D%A1%E8%AF%BB%E8%B7%AF%E5%BE%84%22%7D%0A%20%20W%20--%3E%20L%5B%22%E8%AF%BB%E9%A2%86%E5%AF%BC%E8%80%85%22%5D%0A%20%20W%20--%3E%20F%5B%22%E8%AF%BB%E8%B7%9F%E9%9A%8F%E8%80%85%22%5D%0A%20%20W%20--%3E%20S%5B%22%E5%85%88%20sync%20%E5%86%8D%E8%AF%BB%22%5D%0A%20%20F%20--%3E%20STALE%5B%22%E5%BB%B6%E8%BF%9F%E4%BD%8E%EF%BC%8C%E5%8F%AF%E8%83%BD%E8%AF%BB%E5%88%B0%E6%97%A7%E5%80%BC%22%5D%0A%20%20L%20--%3E%20STRONG%5B%22%E7%BA%BF%E6%80%A7%E4%B8%80%E8%87%B4%22%5D%0A%20%20S%20--%3E%20STRONG%0A%20%20STALE%20--%3E%20TRADE%5B%22%E5%BC%B1%E4%B8%80%E8%87%B4%E6%8D%A2%E5%90%9E%E5%90%90%22%5D%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=s('<p>本课不把 Kafka 早期「用 ZK 做控制器」当成 Zab 本身；那是客户端。也不把 ZK 当 CAP 的 AP 系统：它是 CP 元数据。</p><p>快照与滚动：ZK 有快照+事务日志，与 Raft 快照同族工程税。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 watch 的所有边角、不引入 Zxid 溢出。后课默认：说到 ZK，日志是 Zab，读默认可旧，写走多数派。VR 下一课说明这些「主+日志」比 Paxos 论文更早出现在 Liskov 组。</p><p>前缀广播是 RSM 的投递层。API 把弱读暴露出去，不改变写路径的全序。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Zab：纪元 + ZXID 前缀一致广播。</li><li>ZooKeeper 写线性一致；跟随者读默认可旧。</li><li>与 Raft 同族不同提交与恢复术语。</li><li>出处：Hunt et al., ATC 2010；Junqueira et al., DSN 2011。</li></ul>',7))])}const F=i(d,[["render",D]]);export{m as __pageData,F as default};
